        success: false,
        error: "content must be a valid SHA-256 hash (64 hex characters)",
      });
    }

    const result = await notarizationService.createDynamicNotarization(
      content,
      metadata || "",
      description,
      transferLock
    );

    res.json({
      success: true,
      ...result,
    });
  } catch (error: any) {
